seq = open('region.fasta').read()
lines = seq.strip().split('\n')
bases = ''.join(lines[1:]).upper()
n=len(bases)
def revcomp(s):
    comp={'A':'T','T':'A','G':'C','C':'G','N':'N'}
    return ''.join(comp[b] for b in reversed(s))
rc=revcomp(bases)
stops=('TAA','TAG','TGA')

def orfs(b,minlen=150):
    res=[];i=0;m=len(b)
    while i<=m-3:
        if b[i:i+3]=='ATG':
            j=i
            while j+3<=m:
                if b[j:j+3] in stops: break
                j+=3
            if j-i>=minlen: res.append((j-i,i,j))
            i=j+3
        else: i+=1
    return res

print("Forward ORFs >=150bp (orig coords, fwd strand):")
for L,s,e in sorted(orfs(bases),reverse=True):
    print(f"  {s+1}..{e} len {L}")
print("Reverse ORFs >=150bp (orig coords right->left):")
for L,s,e in sorted(orfs(rc),reverse=True):
    ostart=n-s; oend=n-e+1
    print(f"  {ostart}..{oend} len {L}  (rc {s+1}..{e})")

print("\nGC% by 200bp windows:")
for w in range(0,n,200):
    seg=bases[w:w+200]
    if seg:
        gc=(seg.count('G')+seg.count('C'))/len(seg)*100
        print(f"  {w+1}-{w+len(seg)}: {gc:.1f}%")

longest=max(orfs(rc))
L,rs,re=longest
orf=rc[rs:re]
cod={}
for k in range(0,len(orf)-len(orf)%3,3):
    cod[orf[k:k+3]]=cod.get(orf[k:k+3],0)+1
print("\nReverse ORF codons total:", sum(cod.values()))
print("Top codons:", sorted(cod.items(),key=lambda x:-x[1])[:8])

utr=rc[max(0,rs-40):rs]
print("\n5' UTR (rev gene, rc %d..%d): %s"%(max(0,rs-40),rs,utr))
import re
for m in re.finditer(r'(AGGAGG|GGAGG|GAGG|AGGA)',utr):
    print("  possible SD at rc pos", max(0,rs-40)+m.start(), ":", m.group())

